    },
    {
      "goal": "Search the web for recent articles and lists about top marketing executives to watch, rising marketing leaders, future CMOs, and marketing executives winning awards or recognition in 2024-2026. Look at sources like AdAge '40 Under 40', Forbes CMO Next, Brand Innovators 'Top 100', ANA Marketing Masters, Adweek Brand Genius awards. Compile names of VP/SVP level executives at Fortune 100-500 companies.",
      "tool_name": "spawn_sub_agent",
